(function() {
    'use strict';

    class SystemsMapAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'SystemsMap: Causal Loop Dynamics';
            this.version = '1.1.0';

            // Rounds reference i18n keys so briefings localize (en/es). Effects/logic unchanged.
            this.ROUNDS = [
                { nameKey: 'round1_name', descKey: 'round1_desc' },
                { nameKey: 'round2_name', descKey: 'round2_desc' },
                { nameKey: 'round3_name', descKey: 'round3_desc' },
                { nameKey: 'round4_name', descKey: 'round4_desc' },
                { nameKey: 'round5_name', descKey: 'round5_desc' }
            ];

            // Events: index 0 = no event (round 1). trigger probabilities unchanged.
            // Titles/messages live behind i18n keys and resolve in the current language.
            this.EVENTS = [
                null,
                { trigger: 0.35, key: 'event_p2' },
                { trigger: 0.40, key: 'event_p3' },
                { trigger: 0.45, key: 'event_p4' },
                { trigger: 0.30, key: 'event_p5' }
            ];

            this._hooksBound = false;
            this._lastEvent = null;
        }

        // Resolve a round's translated name/description
        _roundName(idx) { return window.mySimulation.t(this.ROUNDS[idx].nameKey); }
        _roundDesc(idx) { return window.mySimulation.t(this.ROUNDS[idx].descKey); }

        initialize(state) {
            // Reset when there is no history (fresh start OR undo back to round 1).
            // The framework's initialize() snapshots any restored domainState before
            // calling this and re-merges it afterward, so a mid-game resume (which has
            // non-empty history) keeps its saved values regardless. Undo, however, calls
            // adapter.initialize() directly after popping history to empty — keying off
            // an empty history is what makes that path reset correctly.
            var freshStart = (!state.history || state.history.length === 0);
            if (freshStart || !state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    congestionIndex: 1.80,
                    airQuality: 156,
                    transitRidership: 62,
                    avgCommute: 67,
                    publicApproval: 45,
                    equityIndex: 32,
                    politicalCapital: 60,
                    systemsScore: 0,
                    // Canonical grade fields read by the Express grade adapter
                    // (results_utils.php -> express_extractMetrics: domainState.performance.overallScore/grade)
                    performance: { overallScore: 0, grade: 'F', label: 'Developing', compositeScore: 0 },
                    score: 0,
                    congestionHistory: [],
                    airHistory: [],
                    transitHistory: [],
                    commuteHistory: [],
                    approvalHistory: [],
                    equityHistory: [],
                    systemsHistory: [],
                    eventLog: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    policyApproach: 50,
                    stakeholderEngagement: 50,
                    budgetPct: 28,
                    investmentFocus: 'roads'
                };
            }

            this._bindHooks();
            this._updateBriefing(state);
        }

        // Bind framework/DOM hooks exactly once. Refreshing the briefing on the REAL
        // period-advance event (instead of a racy setTimeout) fixes the round the
        // briefing shows after each submit, and keeps it correct on language switch.
        _bindHooks() {
            if (this._hooksBound) return;
            var self = this;
            try {
                if (window.mySimulation && window.mySimulation.eventBus &&
                    typeof window.mySimulation.eventBus.on === 'function') {
                    window.mySimulation.eventBus.on('period:submitted', function() {
                        self._afterAdvance();
                    });
                }
            } catch (e) { /* non-fatal */ }
            try {
                document.addEventListener('express:langchanged', function() {
                    self._updateBriefing(window.mySimulation.state);
                    self._renderEventAlert();
                });
            } catch (e) { /* non-fatal */ }
            this._hooksBound = true;
        }

        // Runs after the framework has advanced currentPeriod. Show the briefing for
        // the period the player is actually on now, and surface the event that just fired.
        _afterAdvance() {
            this._updateBriefing(window.mySimulation.state);
            this._renderEventAlert();
        }

        _renderEventAlert() {
            var alertEl = document.getElementById('eventAlert');
            if (!alertEl) return;
            var ev = this._lastEvent;
            if (ev && ev.triggered) {
                var t = window.mySimulation.t(ev.key + '_title');
                var m = window.mySimulation.t(ev.key + '_msg');
                alertEl.innerHTML = '<strong>' + t + '</strong><br>' + m;
                alertEl.style.display = 'block';
            } else {
                alertEl.innerHTML = '';
                alertEl.style.display = 'none';
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((parseInt(state && state.currentPeriod, 10) || 1) - 1, this.ROUNDS.length - 1);
            if (idx < 0) idx = 0;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this._roundDesc(idx);

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl) nameEl.textContent = this._roundName(idx);

            var policySlider = document.getElementById('policyApproachInput');
            if (policySlider) {
                policySlider.oninput = function() {
                    var v = document.getElementById('policyApproachValue');
                    if (v) v.textContent = policySlider.value;
                };
            }
            var stakeholderSlider = document.getElementById('stakeholderInput');
            if (stakeholderSlider) {
                stakeholderSlider.oninput = function() {
                    var v = document.getElementById('stakeholderValue');
                    if (v) v.textContent = stakeholderSlider.value;
                };
            }
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);

            var policyInput = document.getElementById('policyApproachInput');
            if (policyInput) decisions.policyApproach = parseInt(policyInput.value);

            var stakeholderInput = document.getElementById('stakeholderInput');
            if (stakeholderInput) decisions.stakeholderEngagement = parseInt(stakeholderInput.value);

            var budgetInput = document.getElementById('budgetInput');
            if (budgetInput) decisions.budgetPct = parseInt(budgetInput.value);

            var investmentSelect = document.getElementById('investmentSelect');
            if (investmentSelect) decisions.investmentFocus = investmentSelect.value;

            if (isNaN(decisions.budgetPct) || decisions.budgetPct < 15 || decisions.budgetPct > 45) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        // Derive a 0-100 grade + letter from the current metrics. Single source of truth
        // for both the gradebook (domainState.performance) and the completion summary.
        // NOTE: this does NOT change the underlying systemsScore model — it only exposes
        // a normalized, bounded grade in the shape the reporting layer reads.
        _computePerformance(ds) {
            var totalSystems = ds.systemsScore || 0;
            var congestion   = (ds.congestionIndex != null) ? ds.congestionIndex : 1.8;
            var transit      = (ds.transitRidership != null) ? ds.transitRidership : 62;
            var equity       = (ds.equityIndex != null) ? ds.equityIndex : 32;
            var approval     = (ds.publicApproval != null) ? ds.publicApproval : 45;

            var composite = 0;
            composite += totalSystems * 0.3;
            composite += Math.max(0, (1.8 - congestion) * 50) * 0.2;
            composite += Math.max(0, (transit - 62)) * 2 * 0.15;
            composite += Math.max(0, (equity - 32)) * 1.5 * 0.2;
            composite += Math.max(0, (approval - 45)) * 0.15;

            var overallScore = Math.max(0, Math.min(100, Math.round(composite)));
            var grade = overallScore >= 90 ? 'A'
                      : overallScore >= 80 ? 'B'
                      : overallScore >= 70 ? 'C'
                      : overallScore >= 60 ? 'D' : 'F';
            var labelKey = overallScore >= 80 ? 'label_exemplary'
                         : overallScore >= 55 ? 'label_proficient' : 'label_developing';
            return {
                overallScore: overallScore,
                grade: grade,
                labelKey: labelKey,
                label: window.mySimulation.t(labelKey),
                compositeScore: Math.round(composite)
            };
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var systemic = d.policyApproach / 100;
            var symptomatic = 1 - systemic;
            var inclusive = d.stakeholderEngagement / 100;
            var budgetFactor = d.budgetPct / 28;
            var focus = d.investmentFocus;

            var eventTriggered = false;
            var eventKey = '';
            var eventEffect = { congestion: 0, air: 0, transit: 0, commute: 0, approval: 0, equity: 0, political: 0 };

            var ev = this.EVENTS[period - 1];
            if (ev && Math.random() < ev.trigger + (period * 0.05)) {
                eventTriggered = true;
                eventKey = ev.key;
                if (period === 2) {
                    eventEffect = { congestion: 0.08, air: 12, transit: -2, commute: 3, approval: -5, equity: -4, political: -5 };
                } else if (period === 3) {
                    eventEffect = { congestion: -0.05, air: -5, transit: 1, commute: -2, approval: -8, equity: -3, political: -10 };
                } else if (period === 4) {
                    eventEffect = { congestion: 0.15, air: 8, transit: -6, commute: 8, approval: -10, equity: -2, political: -8 };
                } else if (period === 5) {
                    eventEffect = { congestion: 0.10, air: 6, transit: -3, commute: 5, approval: 3, equity: -2, political: 2 };
                }
            }

            var congestionDelta = 0;
            var airDelta = 0;
            var transitDelta = 0;
            var commuteDelta = 0;
            var approvalDelta = 0;
            var equityDelta = 0;
            var politicalDelta = 0;
            var roundSystemsPoints = 0;

            if (focus === 'roads') {
                congestionDelta = -0.12 * budgetFactor * symptomatic + 0.06 * (period > 2 ? 1 : 0);
                airDelta = 4 * budgetFactor;
                transitDelta = -2 * budgetFactor;
                commuteDelta = -4 * symptomatic * budgetFactor + 2 * (period > 2 ? 1 : 0);
                approvalDelta = 8 * symptomatic - 3 * (period > 3 ? 1 : 0);
                equityDelta = -3 * budgetFactor;
                politicalDelta = 4 * symptomatic - 2 * systemic;
                roundSystemsPoints = 5 + Math.round(systemic * 8);
            } else if (focus === 'transit') {
                congestionDelta = -0.06 * budgetFactor;
                airDelta = -6 * budgetFactor;
                transitDelta = 4 * budgetFactor;
                commuteDelta = -3 * budgetFactor;
                approvalDelta = 3 + 2 * inclusive;
                equityDelta = 5 * budgetFactor * inclusive;
                politicalDelta = 1;
                roundSystemsPoints = 10 + Math.round(systemic * 10);
            } else if (focus === 'land_use') {
                congestionDelta = -0.02 * budgetFactor + (-0.04 * (period > 2 ? 1 : 0) * budgetFactor);
                airDelta = -3 + (-5 * (period > 2 ? 1 : 0));
                transitDelta = 2 + (3 * (period > 2 ? 1 : 0));
                commuteDelta = -1 + (-3 * (period > 2 ? 1 : 0));
                approvalDelta = -2 + (4 * (period > 3 ? 1 : 0));
                equityDelta = 6 * budgetFactor * systemic;
                politicalDelta = -3 + (5 * (period > 3 ? 1 : 0));
                roundSystemsPoints = 15 + Math.round(systemic * 12);
            } else if (focus === 'integrated') {
                var synergy = 1 + (0.15 * period);
                congestionDelta = -0.08 * budgetFactor * synergy;
                airDelta = -8 * budgetFactor * synergy;
                transitDelta = 5 * budgetFactor * synergy * inclusive;
                commuteDelta = -4 * budgetFactor * synergy;
                approvalDelta = -1 + (5 * (period > 2 ? 1 : 0) * inclusive);
                equityDelta = 8 * budgetFactor * inclusive * systemic;
                politicalDelta = -2 + (4 * inclusive * (period > 2 ? 1 : 0));
                roundSystemsPoints = 20 + Math.round(systemic * 15 + inclusive * 8);
            }

            roundSystemsPoints += Math.round(inclusive * 5);
            roundSystemsPoints += Math.round(systemic * 5);

            congestionDelta += eventEffect.congestion;
            airDelta += eventEffect.air;
            transitDelta += eventEffect.transit;
            commuteDelta += eventEffect.commute;
            approvalDelta += eventEffect.approval;
            equityDelta += eventEffect.equity;
            politicalDelta += eventEffect.political;

            ds.congestionIndex = Math.round(Math.max(0.5, Math.min(3.0, ds.congestionIndex + congestionDelta)) * 100) / 100;
            ds.airQuality = Math.round(Math.max(20, Math.min(250, ds.airQuality + airDelta)));
            ds.transitRidership = Math.round(Math.max(20, Math.min(95, ds.transitRidership + transitDelta)));
            ds.avgCommute = Math.round(Math.max(15, Math.min(120, ds.avgCommute + commuteDelta)));
            ds.publicApproval = Math.round(Math.max(5, Math.min(95, ds.publicApproval + approvalDelta)));
            ds.equityIndex = Math.round(Math.max(5, Math.min(95, ds.equityIndex + equityDelta)));
            ds.politicalCapital = Math.round(Math.max(5, Math.min(95, ds.politicalCapital + politicalDelta)));
            ds.systemsScore += roundSystemsPoints;

            ds.congestionHistory.push(ds.congestionIndex);
            ds.airHistory.push(ds.airQuality);
            ds.transitHistory.push(ds.transitRidership);
            ds.commuteHistory.push(ds.avgCommute);
            ds.approvalHistory.push(ds.publicApproval);
            ds.equityHistory.push(ds.equityIndex);
            ds.systemsHistory.push(ds.systemsScore);

            // Canonical grade exposure — read by results_utils.php / analytics / debrief.
            var perf = this._computePerformance(ds);
            ds.performance = perf;
            ds.score = perf.overallScore;

            // Resolve event text in the current language (for history + eventLog/debrief).
            var eventTitle = '';
            if (eventTriggered) {
                eventTitle = window.mySimulation.t(eventKey + '_title');
                ds.eventLog = eventTitle + ': ' + window.mySimulation.t(eventKey + '_msg');
            } else {
                ds.eventLog = '';
            }

            // Stash for the post-advance event-alert render (no DOM writes here / no setTimeout race).
            this._lastEvent = { triggered: eventTriggered, key: eventKey };

            return {
                period: period,
                roundName: this._roundName(Math.min(period - 1, 4)),
                policyApproach: d.policyApproach,
                stakeholderEngagement: d.stakeholderEngagement,
                budgetPct: d.budgetPct,
                investmentFocus: focus,
                congestionIndex: ds.congestionIndex,
                airQuality: ds.airQuality,
                transitRidership: ds.transitRidership,
                avgCommute: ds.avgCommute,
                publicApproval: ds.publicApproval,
                equityIndex: ds.equityIndex,
                politicalCapital: ds.politicalCapital,
                systemsPoints: roundSystemsPoints,
                totalSystemsScore: ds.systemsScore,
                overallScore: perf.overallScore,
                grade: perf.grade,
                score: perf.overallScore,
                eventTriggered: eventTriggered,
                eventKey: eventTriggered ? eventKey : '',
                eventTitle: eventTriggered ? eventTitle : ''
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('congestionDisplay', 'domainState.congestionIndex',
                function(v) { return Number(v).toFixed(2); });
            uiManager.bind('airQualityDisplay', 'domainState.airQuality',
                function(v) { return Math.round(v); });
            uiManager.bind('transitDisplay', 'domainState.transitRidership',
                function(v) { return Math.round(v) + '%'; });
            uiManager.bind('commuteDisplay', 'domainState.avgCommute',
                function(v) { return Math.round(v); });
            uiManager.bind('approvalDisplay', 'domainState.publicApproval',
                function(v) { return Math.round(v) + '%'; });
            uiManager.bind('equityDisplay', 'domainState.equityIndex',
                function(v) { return Math.round(v); });
            uiManager.bind('politicalDisplay', 'domainState.politicalCapital',
                function(v) { return Math.round(v); });
            uiManager.bind('systemsScoreDisplay', 'domainState.systemsScore',
                function(v) { return Math.round(v); });
        }

        getChartConfig() {
            return {
                metricsChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Congestion Index',
                                data: [],
                                borderColor: '#e53935',
                                backgroundColor: 'rgba(229,57,53,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Transit Ridership (%)',
                                data: [],
                                borderColor: '#43a047',
                                backgroundColor: 'rgba(67,160,71,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y1'
                            },
                            {
                                label: 'Public Approval (%)',
                                data: [],
                                borderColor: '#8e24aa',
                                backgroundColor: 'rgba(142,36,170,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'City Metrics Over Time' } },
                        scales: {
                            y: { type: 'linear', position: 'left', title: { display: true, text: 'Congestion Index' }, min: 0.5, max: 3.0 },
                            y1: { type: 'linear', position: 'right', title: { display: true, text: 'Percentage (%)' }, min: 0, max: 100, grid: { drawOnChartArea: false } }
                        }
                    }
                },
                systemsChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Cumulative Systems Score',
                            data: [],
                            backgroundColor: 'rgba(63,81,181,0.6)',
                            borderColor: '#3f51b5',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Systems Thinking Score' } },
