        getChartData(state) {
            var ds = state.domainState || {};
            var hist = ds.congestionHistory || [];
            var labels = hist.map(function(_, i) { return 'R' + (i + 1); });
            return {
                metricsChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.congestionHistory || [] },
                        { data: ds.transitHistory || [] },
                        { data: ds.approvalHistory || [] }
                    ]
                },
