        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var lastRecord = history[history.length - 1];
            var ds = lastRecord.domainState || {};
            var r = lastRecord.results || {};

            // Prefer the snapshotted domainState; fall back to results for older saves.
            var perf = ds.performance || this._computePerformance({
                systemsScore: r.totalSystemsScore,
                congestionIndex: r.congestionIndex,
                transitRidership: r.transitRidership,
                equityIndex: r.equityIndex,
                publicApproval: r.publicApproval
            });

            var totalSystems = (ds.systemsScore != null) ? ds.systemsScore : (r.totalSystemsScore || 0);
            var congestion = (ds.congestionIndex != null) ? ds.congestionIndex : (r.congestionIndex || 1.8);
            var transit = (ds.transitRidership != null) ? ds.transitRidership : (r.transitRidership || 62);
            var equity = (ds.equityIndex != null) ? ds.equityIndex : (r.equityIndex || 32);
            var approval = (ds.publicApproval != null) ? ds.publicApproval : (r.publicApproval || 45);

            var t = function(k) { return window.mySimulation.t(k); };
            var insights = [];
            if (totalSystems > 150) {
                insights.push(t('insight_systems_high'));
            } else if (totalSystems > 100) {
                insights.push(t('insight_systems_mid'));
            } else {
                insights.push(t('insight_systems_low'));
            }
            if (congestion < 1.4) {
                insights.push(t('insight_congestion_good'));
            } else if (congestion > 1.7) {
                insights.push(t('insight_congestion_bad'));
            }
            if (equity > 55) {
                insights.push(t('insight_equity_good'));
            } else {
                insights.push(t('insight_equity_bad'));
            }

            // Re-localize the label to the CURRENT language (the snapshot froze it at
            // submit time); the numeric score and A–F grade are language-neutral.
            var labelKey = perf.overallScore >= 80 ? 'label_exemplary'
                         : perf.overallScore >= 55 ? 'label_proficient' : 'label_developing';

            return {
                totalSystemsScore: totalSystems,
                finalCongestion: congestion,
                finalTransitRidership: transit,
                finalEquityIndex: equity,
                finalApproval: approval,
                overallScore: perf.overallScore,
                grade: perf.grade,
                compositeScore: perf.compositeScore,
                performance: window.mySimulation.t(labelKey),
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var period = state.currentPeriod;

            if (results.investmentFocus === 'roads' && period >= 3) {
                return window.mySimulation.t('hint_roads_late');
            }
            if (results.policyApproach < 30 && period >= 3) {
                return window.mySimulation.t('hint_too_symptomatic');
            }
            if (results.stakeholderEngagement < 30 && results.equityIndex < 40) {
                return window.mySimulation.t('hint_low_engagement');
            }
            if (results.investmentFocus === 'integrated' && results.policyApproach > 60) {
                return window.mySimulation.t('hint_good_systems');
            }
            if (state.domainState.politicalCapital < 30) {
                return window.mySimulation.t('hint_low_political');
            }
            return null;
        }

